class Solution {
    public long totalSwing(int[] readings) {
        int n = readings.length;
        long total = 0;
        for (int i = 0; i < n; i++) {
            int hi = readings[i], lo = readings[i];
            for (int j = i; j < n; j++) {
                hi = Math.max(hi, readings[j]);
                lo = Math.min(lo, readings[j]);
                total += hi - lo;
            }
        }
        return total;
    }
}

