class Solution:
    def totalSwing(self, readings: List[int]) -> int:
        def sum_of_highs(a):
            n = len(a)
            left, stack = [0] * n, []
            for i in range(n):
                while stack and a[stack[-1]] <= a[i]:
                    stack.pop()
                left[i] = i - (stack[-1] if stack else -1)
                stack.append(i)
            stack, total = [], 0
            for i in range(n - 1, -1, -1):
                while stack and a[stack[-1]] < a[i]:
                    stack.pop()
                right = (stack[-1] if stack else n) - i
                total += a[i] * left[i] * right
                stack.append(i)
            return total
        return sum_of_highs(readings) + sum_of_highs([-v for v in readings])

