class Solution {
    private long sumOfHighs(int[] a, int sign) {
        int n = a.length;
        int[] left = new int[n], stack = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && sign * a[stack[top - 1]] <= sign * a[i]) top--;
            left[i] = i - (top > 0 ? stack[top - 1] : -1);
            stack[top++] = i;
        }
        long total = 0;
        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && sign * a[stack[top - 1]] < sign * a[i]) top--;
            int right = (top > 0 ? stack[top - 1] : n) - i;
            total += (long) sign * a[i] * left[i] * right;
            stack[top++] = i;
        }
        return total;
    }

    public long totalSwing(int[] readings) {
        return sumOfHighs(readings, 1) + sumOfHighs(readings, -1);
    }
}

