class Solution {
    long long sumOfHighs(vector<int>& a, int sign) {
        int n = a.size();
        vector<int> left(n), stack;
        for (int i = 0; i < n; i++) {
            while (!stack.empty() && sign * a[stack.back()] <= sign * a[i]) stack.pop_back();
            left[i] = i - (stack.empty() ? -1 : stack.back());
            stack.push_back(i);
        }
        stack.clear();
        long long total = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.empty() && sign * a[stack.back()] < sign * a[i]) stack.pop_back();
            int right = (stack.empty() ? n : stack.back()) - i;
            total += (long long) sign * a[i] * left[i] * right;
            stack.push_back(i);
        }
        return total;
    }

public:
    long long totalSwing(vector<int>& readings) {
        return sumOfHighs(readings, 1) + sumOfHighs(readings, -1);
    }
};

