static long long sumOfHighs(int* a, int n, int sign, int* left, int* stack) {
    int top = 0;
    for (int i = 0; i < n; i++) {
        while (top > 0 && sign * a[stack[top - 1]] <= sign * a[i]) top--;
        left[i] = i - (top > 0 ? stack[top - 1] : -1);
        stack[top++] = i;
    }
    long long total = 0;
    top = 0;
    for (int i = n - 1; i >= 0; i--) {
        while (top > 0 && sign * a[stack[top - 1]] < sign * a[i]) top--;
        int right = (top > 0 ? stack[top - 1] : n) - i;
        total += (long long) sign * a[i] * left[i] * right;
        stack[top++] = i;
    }
    return total;
}

long long totalSwing(int* readings, int readingsSize) {
    int* left = malloc(readingsSize * sizeof(int));
    int* stack = malloc(readingsSize * sizeof(int));
    long long total = sumOfHighs(readings, readingsSize, 1, left, stack) + sumOfHighs(readings, readingsSize, -1, left, stack);
    free(left);
    free(stack);
    return total;
}
